<?php include 'verifica_login.php'; include 'conexao.php'; include '_layout.php';$id=id_get('id');
if($_SERVER['REQUEST_METHOD']==='POST'){ $ide=(int)($_POST['id_edicao']??0);$titulo=esc($conexao,$_POST['titulo']??'');$paginas=esc($conexao,$_POST['paginas']??'');$doi=esc($conexao,$_POST['doi']??'');$status=esc($conexao,$_POST['status']??'');$autores=$_POST['autores']??[];if(!$ide||$titulo==='')erro('Informe a edição e o título.');$ok=mysqli_query($conexao,"UPDATE artigos SET id_edicao=$ide, titulo='$titulo', paginas='$paginas', doi='$doi', status='$status' WHERE id_artigo=$id");if(!$ok)erro(mysqli_error($conexao));mysqli_query($conexao,"DELETE FROM artigo_autor WHERE id_artigo=$id");foreach($autores as $aid){$aid=(int)$aid;if($aid>0&&!mysqli_query($conexao,"INSERT INTO artigo_autor (id_artigo,id_autor) VALUES ($id,$aid)"))erro(mysqli_error($conexao));}redirect('lista_artigos.php');}
$r=mysqli_query($conexao,"SELECT * FROM artigos WHERE id_artigo=$id");if(!$r||mysqli_num_rows($r)!==1)erro('Artigo não encontrado.');$row=mysqli_fetch_assoc($r);$ed=mysqli_query($conexao,"SELECT e.id_edicao, e.numero, e.volume, r.nome FROM edicoes e INNER JOIN revistas r ON r.id_revista=e.id_revista ORDER BY r.nome,e.id_edicao DESC");$au=mysqli_query($conexao,"SELECT id_autor,nome FROM autores ORDER BY nome");$sel=[];$sr=mysqli_query($conexao,"SELECT id_autor FROM artigo_autor WHERE id_artigo=$id");while($x=mysqli_fetch_assoc($sr))$sel[]=(int)$x['id_autor'];
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Editar Artigo</title><?php include 'includes_painel/head.php'; ?><?php include '_form_style.php'; ?></head><body><?php include 'includes_painel/header.php'; ?><div class="crud"><div class="card"><h1>Editar Artigo</h1><form method="post"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><div class="grid"><div class="campo full"><label>Edição</label><select name="id_edicao" required><?php while($e=mysqli_fetch_assoc($ed)):?><option value="<?=$e['id_edicao']?>" <?=($row['id_edicao']??0)==$e['id_edicao']?'selected':''?>><?=h($e['nome'].' — edição '.$e['numero'].' / volume '.$e['volume'])?></option><?php endwhile;?></select></div><div class="campo full"><label>Título</label><input name="titulo" required value="<?=h($row['titulo'])?>"></div><div class="campo"><label>Páginas</label><input name="paginas" value="<?=h($row['paginas']??'')?>"></div><div class="campo"><label>DOI</label><input name="doi" value="<?=h($row['doi']??'')?>"></div><div class="campo"><label>Status</label><select name="status"><?php foreach(['Publicado','Em Revisão','Arquivado'] as $op):?><option <?=($row['status']??'')===$op?'selected':''?>><?=h($op)?></option><?php endforeach;?></select></div><div class="campo"><label>Autores</label><select name="autores[]" multiple size="6"><?php while($a=mysqli_fetch_assoc($au)):?><option value="<?=$a['id_autor']?>" <?=in_array((int)$a['id_autor'],$sel,true)?'selected':''?>><?=h($a['nome'])?></option><?php endwhile;?></select></div></div><div class="acoes"><button class="btn salvar">Salvar alterações</button><a class="btn voltar" href="lista_artigos.php">Cancelar</a></div></form></div></div></body></html>
